/**
 * Everything that changes between machines/CI lives here, read from environment variables
 * with sensible defaults. See README.md → "Configuration" for the full list.
 */

/** Android application id / iOS bundle id, from ../../app.json. */
export const APP_ID = {
  android: 'com.red30tech.dashboard',
  ios: 'com.red30tech.dashboard',
} as const;

/** Launch activity generated by Expo prebuild (android/app/src/main/.../MainActivity). */
export const ANDROID_LAUNCH_ACTIVITY = '.MainActivity';

const env = (name: string): string | undefined => {
  const value = process.env[name]?.trim();
  return value ? value : undefined;
};

export const config = {
  android: {
    /** Path to the .apk to install. If unset, the already-installed app is launched. */
    app: env('ANDROID_APP'),
    deviceName: env('ANDROID_DEVICE_NAME') ?? 'Android Emulator',
    /** adb serial (from `adb devices`); needed only when several devices are connected. */
    udid: env('ANDROID_UDID'),
    platformVersion: env('ANDROID_PLATFORM_VERSION'),
    /**
     * Emulator (AVD) name from `emulator -list-avds`. When set, Appium boots it if it is
     * not already running. When unset, a device must already be connected (`adb devices`).
     */
    avd: env('ANDROID_AVD'),
  },
  ios: {
    /** Path to the simulator .app (or device .ipa). If unset, the already-installed app is launched. */
    app: env('IOS_APP'),
    deviceName: env('IOS_DEVICE_NAME') ?? 'iPhone 17',
    udid: env('IOS_UDID'),
    platformVersion: env('IOS_PLATFORM_VERSION'),
  },
  /** Default timeout (ms) for waits on elements. */
  waitTimeout: Number(env('E2E_WAIT_TIMEOUT') ?? 15_000),
  /** Port the Appium server started by @wdio/appium-service listens on. */
  appiumPort: Number(env('APPIUM_PORT') ?? 4723),
} as const;
